//---------------------------------------------------------------------------//
// Unit tests for tools/lina/qrot
// Initial implementation generated by GitHub CoPilot (GPT-4.1)
//---------------------------------------------------------------------------//
#include "tools/lina/qrot"

#include "tools/lina/mat4"
#include "tools/lina/vec"
#include <gtest/gtest.h>

#include <cmath>
// To avoid dependence on CLHEP/Geant4 math, define M_PI if cmath doesn't
// provide it (Windows)
#ifndef M_PI
#  define M_PI 3.14159265358979323846
#endif

#include <gtest/gtest.h>

namespace tools
{
//---------------------------------------------------------------------------//
TEST(QRot, DefaultIsIdentity)
{
  qrotf q;
  EXPECT_FLOAT_EQ(q.quat().v0(), 0.0f);
  EXPECT_FLOAT_EQ(q.quat().v1(), 0.0f);
  EXPECT_FLOAT_EQ(q.quat().v2(), 0.0f);
  EXPECT_FLOAT_EQ(q.quat().v3(), 1.0f);
}

TEST(QRot, AxisAngleRotation)
{
  vec3f axis(0.0f, 0.0f, 1.0f);
  float angle = static_cast<float>(M_PI) / 2.0f;  // 90 degrees
  qrotf q(axis, angle);

  // Should rotate (1,0,0) to (0,1,0)
  vec3f v(1.0f, 0.0f, 0.0f), out;
  q.mul_vec(v, out);
  EXPECT_NEAR(out.x(), 0.0f, 1e-6f);
  EXPECT_NEAR(out.y(), 1.0f, 1e-6f);
  EXPECT_NEAR(out.z(), 0.0f, 1e-6f);
}

TEST(QRot, FromToRotation)
{
  vec3f from(1.0f, 0.0f, 0.0f);
  vec3f to(0.0f, 1.0f, 0.0f);
  qrotf q(from, to);

  vec3f v(1.0f, 0.0f, 0.0f), out;
  q.mul_vec(v, out);
  EXPECT_NEAR(out.x(), 0.0f, 1e-6f);
  EXPECT_NEAR(out.y(), 1.0f, 1e-6f);
  EXPECT_NEAR(out.z(), 0.0f, 1e-6f);
}

TEST(QRot, QuaternionMultiplication)
{
  vec3f axis_z(0.0f, 0.0f, 1.0f);
  vec3f axis_y(0.0f, 1.0f, 0.0f);
  float angle = static_cast<float>(M_PI) / 2.0f;
  qrotf qz(axis_z, angle);
  qrotf qy(axis_y, angle);

  // Should rotate (1,0,0) first 90 deg about Y, then 90 deg about Z
  qrotf q = qz * qy;
  vec3f v(1.0f, 0.0f, 0.0f), out;
  q.mul_vec(v, out);
  // After Y: (0,0,-1), after Z: (0,1,0)
  EXPECT_NEAR(out.x(), 0.0f, 1e-6f);
  EXPECT_NEAR(out.y(), 1.0f, 1e-6f);
  EXPECT_NEAR(out.z(), 0.0f, 1e-6f);
}

TEST(QRot, InverseRotation)
{
  vec3f axis(0.0f, 0.0f, 1.0f);
  float angle = static_cast<float>(M_PI) / 2.0f;
  qrotf q(axis, angle);

  qrotf qinv;
  ASSERT_TRUE(q.inverse(qinv));

  vec3f v(1.0f, 0.0f, 0.0f), out, out_inv;
  q.mul_vec(v, out);
  qinv.mul_vec(out, out_inv);

  EXPECT_NEAR(out_inv.x(), v.x(), 1e-6f);
  EXPECT_NEAR(out_inv.y(), v.y(), 1e-6f);
  EXPECT_NEAR(out_inv.z(), v.z(), 1e-6f);
}

TEST(QRot, ValueAxisAngle)
{
  vec3f axis(0.0f, 1.0f, 0.0f);
  float angle = static_cast<float>(M_PI) / 3.0f;
  qrotf q(axis, angle);

  vec3f out_axis;
  float out_angle;
  ASSERT_TRUE(q.value(out_axis, out_angle));
  // Axis should be normalized and close to input
  EXPECT_NEAR(out_axis.x(), axis.x(), 1e-6f);
  EXPECT_NEAR(out_axis.y(), axis.y(), 1e-6f);
  EXPECT_NEAR(out_axis.z(), axis.z(), 1e-6f);
  EXPECT_NEAR(out_angle, angle, 1e-6f);
}

TEST(QRot, MatrixConversion)
{
  vec3f axis(0.0f, 0.0f, 1.0f);
  float angle = static_cast<float>(M_PI) / 2.0f;
  qrotf q(axis, angle);

  mat4f m;
  q.value(m);

  qrotf q2;
  q2.set_value(m);

  // Last component may vary slightly, so exact comparison fails
  EXPECT_FALSE(q == q2);
  EXPECT_FLOAT_EQ(q.quat()[0], q2.quat()[0]);
  EXPECT_FLOAT_EQ(q.quat()[1], q2.quat()[1]);
  EXPECT_FLOAT_EQ(q.quat()[2], q2.quat()[2]);
  EXPECT_FLOAT_EQ(q.quat()[3], q2.quat()[3]);
}

TEST(QRot, MulVecInPlace)
{
  vec3f axis(0.0f, 0.0f, 1.0f);
  float angle = static_cast<float>(M_PI) / 2.0f;
  qrotf q(axis, angle);

  vec3f v(1.0f, 0.0f, 0.0f);
  q.mul_vec(v);
  EXPECT_NEAR(v.x(), 0.0f, 1e-6f);
  EXPECT_NEAR(v.y(), 1.0f, 1e-6f);
  EXPECT_NEAR(v.z(), 0.0f, 1e-6f);
}

//---------------------------------------------------------------------------//
}  // namespace tools
